class BoundaryError(Exception):
    pass

def require(value, code):
    if not value:
        raise BoundaryError(code)

def public_file(path, expected=None, mode=None, maximum=16 * 1024**2):
    before = path.lstat()
    require(stat.S_ISREG(before.st_mode) and before.st_uid == os.getuid() and before.st_nlink == 1 and not path.is_symlink() and path.resolve(strict=True) == path and before.st_size <= maximum, "public-file")
    require(mode is None or stat.S_IMODE(before.st_mode) == mode, "public-mode")
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        value = os.fstat(fd)
        require((value.st_dev, value.st_ino) == (before.st_dev, before.st_ino), "public-identity")
        chunks = []
        size = 0
        while chunk := os.read(fd, 65536):
            size += len(chunk)
            require(size <= maximum, "public-size")
            chunks.append(chunk)
        after = os.fstat(fd)
        require((before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) == (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns), "public-changed")
    finally:
        os.close(fd)
    data = b"".join(chunks)
    require(expected is None or hashlib.sha256(data).hexdigest() == expected, "public-hash")
    return data

def preflight():
    tree = TREE.lstat()
    require(stat.S_ISDIR(tree.st_mode) and tree.st_uid == os.getuid() and stat.S_IMODE(tree.st_mode) == 0o700 and TREE.resolve(strict=True) == TREE, "source-root")
    data = zlib.decompress(base64.b64decode(SOURCE_Z, validate=True))
    require(len(data) <= 1024 * 1024 and hashlib.sha256(data).hexdigest() == SOURCE_MANIFEST_SHA, "manifest-frozen")
    manifest = json.loads(data)
    require(len(manifest) == 1457 and len(LINKS) == 108, "manifest-count")
    for relative, entry in manifest.items():
        require(not Path(relative).is_absolute() and ".." not in Path(relative).parts, "manifest-path")
        path = TREE / relative
        if entry["mode"] == "120000":
            require(path.is_symlink() and relative == "AGENTS.md" and os.readlink(path) == "CLAUDE.md", "source-link")
            payload = os.readlink(path).encode()
        else:
            require(entry["mode"] in ("100644", "100755"), "source-mode")
            payload = public_file(path, entry["sha256"], 0o755 if entry["mode"] == "100755" else 0o644)
        require(len(payload) == entry["bytes"] and hashlib.sha256(payload).hexdigest() == entry["sha256"], "source-binding")
    for relative, entry in LINKS.items():
        path = TREE / relative
        require(path.is_symlink() and path.lstat().st_nlink == 1 and path.lstat().st_uid == os.getuid() and os.readlink(path) == entry["link"] and str(path.resolve(strict=True)) == entry["canonical"], "dependency-link")
    for path, entry in PRIMARY.items():
        require(len(public_file(Path(path), entry["sha256"], entry["mode"])) == entry["bytes"], "vitest-primary")
    require(json.loads(public_file((TREE / "node_modules/vitest/package.json").resolve(strict=True)))["version"] == "4.1.6", "vitest-version")
    public_file(TREE / "apps/web/worker-configuration.d.ts", "1803d60aa0818e5a3a7630807466ffaae8fdeb0fd85b7fa59431638fc5a479fa")
    loader = public_file(LOADER, LOADER_SHA, 0o600, LIMITS["materialBytes"])
    own = public_file(Path(__file__).resolve(strict=True), mode=0o600, maximum=LIMITS["materialBytes"])
    require(len(loader) + len(own) <= LIMITS["materialBytes"], "material-bound")
    node = NODE.lstat()
    require(NODE.resolve(strict=True) == NODE and stat.S_ISREG(node.st_mode) and not NODE.is_symlink() and node.st_uid == 0 and node.st_nlink == 2 and stat.S_IMODE(node.st_mode) == 0o555 and node.st_size == 64896912, "node-metadata")
    return {"sourceFiles": 1457, "publicLinks": 108, "cases": 3, "nodeMetadata": True, "actualNodeVersion": False}

def identity(path, directory, mode, expected=None):
    value = path.lstat()
    require(stat.S_ISDIR(value.st_mode) if directory else stat.S_ISREG(value.st_mode), "root-type")
    require(not path.is_symlink() and path.resolve(strict=True) == path and value.st_uid == os.getuid() and stat.S_IMODE(value.st_mode) == mode and (directory or value.st_nlink == 1), "root-identity")
    pair = (value.st_dev, value.st_ino)
    require(expected is None or expected == pair, "root-replaced")
    return value, pair

def metadata_guard(root_identity, tmp_identity, control_identity):
    root, _ = identity(ROOT, True, 0o700, root_identity)
    tmp, _ = identity(TMP, True, 0o700, tmp_identity)
    require(tmp.st_size <= LIMITS["tmpBytes"] and list(TMP.iterdir()) == [], "tmp-bound")
    entries = {path.name for path in ROOT.iterdir()}
    require(entries <= {"tool-tmp", "control.ndjson", "receipt.json"} and {"tool-tmp", "control.ndjson"} <= entries, "root-entries")
    control, _ = identity(CONTROL, False, 0o600, control_identity)
    require(control.st_size <= LIMITS["controlBytes"], "control-bound")
    size = root.st_size + tmp.st_size + control.st_size
    if "receipt.json" in entries:
        receipt, _ = identity(RECEIPT, False, 0o600)
        require(receipt.st_size <= LIMITS["resultBytes"], "receipt-bound")
        size += receipt.st_size
    require(size <= LIMITS["rootBytes"] and control.st_size <= LIMITS["logBytes"], "root-size")
    return size

SCHEMAS = {
    "node-binding": {"canonical", "version"}, "fork-start": {"count", "detached"}, "suite-start": set(), "case": {"index", "passed"},
    "worker-closed": {"count", "detect", "extract", "maximum", "online", "exit", "readEnd", "readClose", "terminateHandled", "afterAll"},
    "fork-closed": {"count", "actualExit", "ipcDisconnect", "connectedFalse", "channelReleased", "ipcEOF", "stdinClose", "readEnd", "readClose", "close", "normalPoolStop", "exitKind"},
    "summary": {"ok", "cases", "modulePassed", "runEnded", "suiteEnded", "afterAllEnded", "denied"},
    "denied": {"kind"}, "failure": {"code"},
    "expected-disabled": {"family", "site", "count"},
}

def strict_object(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result, "frame-duplicate-key")
        result[key] = value
    return result

def reject_constant(_value):
    raise BoundaryError("frame-number")

def decode(packet, group):
    require(type(packet) is dict and type(packet.get("event")) is str and packet["event"] in SCHEMAS, "frame-event")
    event = packet["event"]
    native_fields = {"native"} if event == "denied" and packet.get("kind") == "native-module" else {"filesystem"} if event == "denied" and packet.get("kind") == "filesystem" else set()
    require(set(packet) == SCHEMAS[event] | {"event", "context"} | native_fields, "frame-shape")
    expected_context = "fork" if event == "worker-closed" else "main"
    require(packet["context"] in ("main", "fork") if event in ("node-binding", "denied", "failure", "expected-disabled") else packet["context"] == expected_context, "frame-context")
    if event == "node-binding": require(packet["canonical"] is True and packet["version"] is True, "node-binding")
    if event == "fork-start":
        require(type(packet["count"]) is int and packet["count"] == 1 and packet["detached"] is False, "fork-owned-handle")
    if event == "case": require(type(packet["index"]) is int and packet["index"] in (0, 1, 2) and packet["passed"] is True, "case-frame")
    if event == "worker-closed":
        require((packet["count"], packet["detect"], packet["extract"]) == (16, 3, 13) and all(type(packet[key]) is int for key in ("count", "detect", "extract", "maximum")) and packet["maximum"] in (1, 2) and type(packet["online"]) is int and 0 <= packet["online"] <= 16 and all(packet[key] is True for key in ("exit", "readEnd", "readClose", "terminateHandled", "afterAll")), "worker-frame")
    if event == "fork-closed": require(type(packet["count"]) is int and packet["count"] == 1 and all(packet[key] is True for key in SCHEMAS[event] - {"count", "exitKind", "ipcEOF"}) and packet["ipcEOF"] is None and packet["exitKind"] in {"exit0", "pool-SIGTERM"}, "fork-frame")
    if event == "summary": require(type(packet["cases"]) is int and 0 <= packet["cases"] <= 3 and all(type(packet[key]) is bool for key in SCHEMAS[event] - {"cases"}), "summary-frame")
    if event == "expected-disabled": require(packet["family"] == "fsevents" and packet["site"] == "optional-preload" and type(packet["count"]) is int and packet["count"] == 1, "optional-disabled-enum")
    if event == "denied":
        require(packet["kind"] in {"metadata", "binding", "filesystem", "network", "process", "worker", "case", "native-module"}, "denial-enum")
        if packet["kind"] == "filesystem":
            filesystem = packet["filesystem"]
            require(type(filesystem) is dict and set(filesystem) == {"method", "site", "scope"}, "filesystem-diagnostic-shape")
            require(type(filesystem["method"]) is str and filesystem["method"] in {'rm', 'readdir', 'unlinkSync', 'watchFile', 'access', 'rmSync', 'chmod', 'cpSync', 'appendFileSync', 'statSync', 'writeSync', 'mkdirSync', 'opendirSync', 'cp', 'accessSync', 'truncate', 'unlink', 'writeFile', 'lstat', 'renameSync', 'realpathSync', 'readFile', 'chown', 'existsSync', 'ftruncate', 'mkdtempSync', 'writev', 'appendFile', 'writeFileSync', 'rmdir', 'copyFileSync', 'truncateSync', 'utimes', 'opendir', 'symlinkSync', 'lstatSync', 'mkdir', 'rename', 'write', 'open', 'createWriteStream', 'openSync', 'mkdtemp', 'writevSync', 'linkSync', 'utimesSync', 'registerProjects', 'createReadStream', 'copyFile', 'realpath', 'readdirSync', 'chmodSync', 'readFileSync', 'chownSync', 'watch', 'symlink', 'link', 'stat', 'ftruncateSync', 'rmdirSync'} and type(filesystem["site"]) is str and filesystem["site"] in {"NORMALIZE", "DB_SUFFIX", "READ_SCOPE", "OPEN_FLAGS", "MUTATION", "TMP_EMPTY", "PROJECT_BINDING", "RM_ARGUMENTS", "RM_STATE"} and (filesystem["scope"] is None or type(filesystem["scope"]) is str and filesystem["scope"] in {"OUTSIDE", "TMP", "PROJECT_TMP"}), "filesystem-diagnostic-enum")
        if packet["kind"] == "native-module":
            native = packet["native"]
            require(type(native) is dict and set(native) == {"family", "site", "contextMatch", "parentMatch", "ancestorMatch"}, "native-diagnostic-shape")
            require(type(native["family"]) is str and native["family"] in {"fsevents", "rolldown", "lightningcss", "other"} and type(native["site"]) is str and native["site"] in {"OPTIONAL_CONTEXT", "OPTIONAL_MODULE", "OPTIONAL_PARENT", "OPTIONAL_ANCESTOR", "OPTIONAL_BINDING", "DLOPEN_GATE", "DLOPEN_METADATA", "SQLITE_BUILTIN", "SQLITE_RESOLVE"} and all(native[key] is None or type(native[key]) is bool for key in ("contextMatch", "parentMatch", "ancestorMatch")), "native-diagnostic-enum")
    if event == "failure": require(packet["code"] in {"BODY_DEADLINE", "RESOURCE_DENIED", "FORK_CLOSURE", "TOOL_FAILURE"}, "failure-enum")
    return packet

def group_state(group):
    if group is None: return "unknown"
    try:
        os.killpg(group, 0)
        return "alive"
    except ProcessLookupError: return "absent"
    except OSError: return "unknown"

def signal_group(group, value):
    if group is None: return "not-attempted"
    try:
        os.killpg(group, value)
        return "sent-success"
    except ProcessLookupError: return "ESRCH-absent"
    except PermissionError: return "EPERM-unknown"
    except OSError: return "other-unknown"

def run():
    preflight()
    require(not os.path.lexists(ROOT), "fresh-root")
    require(ROOT.parent.resolve(strict=True) == ROOT.parent and ROOT.parent.is_dir(), "root-parent")
    os.mkdir(ROOT, 0o700)
    _, root_identity = identity(ROOT, True, 0o700)
    os.mkdir(TMP, 0o700)
    _, tmp_identity = identity(TMP, True, 0o700)
    control_fd = os.open(CONTROL, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_APPEND | os.O_NOFOLLOW, 0o600)
    _, control_identity = identity(CONTROL, False, 0o600)
    selector = selectors.DefaultSelector()
    child = None
    group = None
    packets = []
    checkpoints = []
    control_offset = 0
    control_pending = b""
    discarded = {"stdout": 0, "stderr": 0}
    eof = set()
    normal = False
    failure = None
    term = "not-attempted"
    kill = "not-attempted"
    started = time.monotonic()
    outer_deadline = started + LIMITS["outerSeconds"]
    try:
        metadata_guard(root_identity, tmp_identity, control_identity)
        environment = {"PATH": str(NODE.parent) + ":/usr/bin:/bin", "TMPDIR": str(TMP), "NODE_ENV": "test", "CI": "1", "NO_COLOR": "1",
                       "HOLLOW_PARSER_ROOT": str(ROOT), "HOLLOW_PARSER_CONTROL_FD": str(control_fd),
                       "HOLLOW_PARSER_CONTROL_IDENTITY": json.dumps({"dev": control_identity[0], "ino": control_identity[1]}, separators=(",", ":")),
                       "HOLLOW_PARSER_TMP_IDENTITY": json.dumps({"dev": tmp_identity[0], "ino": tmp_identity[1]}, separators=(",", ":"))}
        child = subprocess.Popen([str(NODE), str(LOADER)], cwd=TREE, env=environment, stdin=subprocess.DEVNULL,
                                 stdout=subprocess.PIPE, stderr=subprocess.PIPE, pass_fds=(control_fd,), start_new_session=True)
        require(child.stdout is not None and child.stderr is not None and child.pid > 0, "node-handles")
        require(os.getpgid(child.pid) == child.pid and child.pid != os.getpgid(0), "node-pg")
        group = child.pid
        for stream in (child.stdout, child.stderr): selector.register(stream, selectors.EVENT_READ)
        while selector.get_map() or child.poll() is None:
            require(time.monotonic() < min(started + 210, outer_deadline - 30), "body-closure-deadline")
            metadata_guard(root_identity, tmp_identity, control_identity)
            for key, _ in selector.select(0.2):
                value = os.read(key.fd, 65536)
                channel = "stdout" if key.fileobj is child.stdout else "stderr"
                if not value:
                    eof.add(channel); selector.unregister(key.fileobj)
                else:
                    discarded[channel] += len(value)
                    require(sum(discarded.values()) <= LIMITS["logBytes"], "raw-discard-bound")
            size = os.fstat(control_fd).st_size
            require(size <= LIMITS["controlBytes"], "control-bound")
            value = os.pread(control_fd, size - control_offset, control_offset)
            control_offset += len(value)
            control_pending += value
            while b"\n" in control_pending:
                line, control_pending = control_pending.split(b"\n", 1)
                require(len(line) + 1 <= LIMITS["frameBytes"] and len(packets) < LIMITS["frames"], "frame-bound")
                packet = decode(json.loads(line, object_pairs_hook=strict_object, parse_constant=reject_constant), group)
                if packet["event"] == "expected-disabled":
                    previous_disabled = [value for value in packets if value["event"] == "expected-disabled"]
                    require(len(previous_disabled) < 2 and all(value["context"] != packet["context"] for value in previous_disabled) and any(value["event"] == "node-binding" and value["context"] == packet["context"] for value in packets), "optional-disabled-bound")
                packets.append(packet)
                checkpoint = packet["context"] + "-" + packet["event"]
                if checkpoint not in checkpoints: checkpoints.append(checkpoint)
                require(len(checkpoints) <= LIMITS["checkpoints"], "checkpoint-bound")
                require(packet["event"] not in ("failure", "denied"), "tool-failure-held")
            require(len(control_pending) <= LIMITS["frameBytes"], "partial-frame")
        child.wait(timeout=min(1, max(0.001, outer_deadline - time.monotonic())))
        require(child.returncode == 0 and eof == {"stdout", "stderr"} and group_state(group) == "absent" and not control_pending, "node-exit-eof-pg")
        summaries = [packet for packet in packets if packet["event"] == "summary"]
        require(len(summaries) == 1 and summaries[0]["ok"] is True and summaries[0]["cases"] == 3 and all(summaries[0][key] is True for key in ("modulePassed", "runEnded", "suiteEnded", "afterAllEnded")) and summaries[0]["denied"] is False, "normal-summary")
        require([packet["index"] for packet in packets if packet["event"] == "case"] == [0, 1, 2], "case-order")
        for event in ("fork-start", "suite-start", "worker-closed", "fork-closed"):
            require(sum(packet["event"] == event for packet in packets) == 1, "receipt-count")
        require(all(packet["ipcEOF"] is None and packet["ipcDisconnect"] is True and packet["connectedFalse"] is True and packet["channelReleased"] is True for packet in packets if packet["event"] == "fork-closed"), "ipc-closure-unproven")
        require(sorted(packet["context"] for packet in packets if packet["event"] == "node-binding") == ["fork", "main"], "actual-version-receipts")
        metadata_guard(root_identity, tmp_identity, control_identity)
        normal = True
    except (BoundaryError, OSError, ValueError, TypeError, KeyError, OverflowError, subprocess.SubprocessError):
        failure = "held-unproven"
        if child is not None and group is not None:
            tail_started = time.monotonic()
            if group_state(group) != "absent":
                term = signal_group(group, signal.SIGTERM)
                deadline = min(tail_started + 10, outer_deadline)
                while group_state(group) == "alive" and time.monotonic() < deadline:
                    child.poll(); time.sleep(0.2)
                if group_state(group) != "absent":
                    kill = signal_group(group, signal.SIGKILL)
                    deadline = min(tail_started + 20, outer_deadline)
                    while group_state(group) == "alive" and time.monotonic() < deadline:
                        child.poll(); time.sleep(0.2)
            deadline = min(tail_started + 30, outer_deadline)
            while selector.get_map() and time.monotonic() < deadline:
                for key, _ in selector.select(min(0.2, max(0, deadline - time.monotonic()))):
                    value = os.read(key.fd, 65536)
                    channel = "stdout" if key.fileobj is child.stdout else "stderr"
                    if not value: eof.add(channel); selector.unregister(key.fileobj)
                    else: discarded[channel] += len(value)
            child.poll()
    finally:
        selector.close()
        if child is not None:
            if child.stdout is not None: child.stdout.close()
            if child.stderr is not None: child.stderr.close()
        os.close(control_fd)
    denials = [{"context": packet["context"], "kind": packet["kind"], "source": "loader", "site": None,
                **({"native": packet["native"]} if packet["kind"] == "native-module" else {"filesystem": packet["filesystem"]} if packet["kind"] == "filesystem" else {})}
               for packet in packets if packet["event"] == "denied"][:4]
    expected_disabled = [{"context": packet["context"], "family": packet["family"], "site": packet["site"], "count": packet["count"]}
                         for packet in packets if packet["event"] == "expected-disabled"]
    result = {"ok": normal, "held": not normal, "failure": failure, "actualExit": None if child is None else child.returncode,
              "nodePG": group_state(group), "term": term, "kill": kill, "stdoutEOF": "stdout" in eof, "stderrEOF": "stderr" in eof,
              "pipeFDClosed": child is not None and child.stdout is not None and child.stderr is not None and child.stdout.closed and child.stderr.closed, "controlFDClosed": True,
              "rawDiscardBytes": discarded, "frames": len(packets), "controlBytes": control_offset,
              "denials": denials, "expectedDisabled": expected_disabled, "checkpoints": checkpoints, "casesPassed": sum(packet["event"] == "case" for packet in packets),
              "workerReceipt": any(packet["event"] == "worker-closed" for packet in packets),
              "forkReceipt": any(packet["event"] == "fork-closed" for packet in packets), "ipcEOF": None, "databaseAudit": False}
    if normal:
        require(time.monotonic() < outer_deadline and result["pipeFDClosed"] and result["nodePG"] == "absent" and term == kill == "not-attempted", "normal-final-gate")
        payload = json.dumps(result, separators=(",", ":")).encode()
        require(len(payload) <= LIMITS["resultBytes"], "result-bound")
        fd = os.open(RECEIPT, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        try: require(os.write(fd, payload) == len(payload), "result-write")
        finally: os.close(fd)
        metadata_guard(root_identity, tmp_identity, control_identity)
    print(json.dumps(result, separators=(",", ":")))
    return 0 if normal else 1

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--run", action="store_true")
    arguments = parser.parse_args()
    if arguments.run: return run()
    result = preflight()
    print(json.dumps({"publicPreflight": result, "actualRun": False, "newRootProbe": False}, separators=(",", ":")))
    return 0

if __name__ == "__main__":
    os.umask(0o077)
    try: sys.exit(main())
    except (BoundaryError, OSError, ValueError, TypeError, KeyError, OverflowError, subprocess.SubprocessError):
        print(json.dumps({"ok": False, "held": True, "failure": "preflight-or-boundary", "databaseAudit": False}, separators=(",", ":")))
        sys.exit(1)
